import { Component, signal } from '@angular/core';
import {
	NgbNavContent,
	NgbNav,
	NgbNavItem,
	NgbNavItemRole,
	NgbNavLinkButton,
	NgbNavLinkBase,
	NgbNavOutlet,
} from '@ng-bootstrap/ng-bootstrap/nav';

@Component({
	selector: 'ngbd-nav-dynamic',
	imports: [NgbNavContent, NgbNav, NgbNavItem, NgbNavItemRole, NgbNavLinkButton, NgbNavLinkBase, NgbNavOutlet],
	templateUrl: './nav-dynamic.html',
	styles: `
		.close {
			font-size: 1.4rem;
			opacity: 0.1;
			transition: opacity 0.3s;
		}
		.nav-link:hover > .close {
			opacity: 0.8;
		}
	`,
})
export class NgbdNavDynamic {
	readonly navs = signal([1, 2, 3, 4, 5]);
	private counter = this.navs().length + 1;
	readonly active = signal(1);

	close(event: MouseEvent, toRemove: number) {
		this.navs.update((navs) => navs.filter((id) => id !== toRemove));
		event.preventDefault();
		event.stopImmediatePropagation();
	}

	add(event: MouseEvent) {
		this.navs.update((navs) => [...navs, this.counter++]);
		event.preventDefault();
	}
}
